CREATE OR REPLACE FUNCTION private.zeyds_accept_ride_atomic(ride_uuid uuid, driver_uuid uuid, actor_uuid uuid, operation_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  ride_row public.rides%rowtype;
  driver_row public.ride_drivers%rowtype;
  vehicle_row public.driver_vehicles%rowtype;
  wallet_row public.professional_wallets%rowtype;
  commission_value integer;
begin
  if operation_key is null or length(trim(operation_key)) < 8 then raise exception 'idempotency_key_invalid'; end if;
  if actor_uuid is null then raise exception 'authentication_required'; end if;
  if not exists (
    select 1 from public.ride_drivers d join public.providers p on p.id = d.provider_id
    where d.id = driver_uuid and p.auth_user_id = actor_uuid
  ) and not public.is_admin() then raise exception 'driver_forbidden'; end if;

  select * into ride_row from public.rides where id = ride_uuid for update;
  if not found then raise exception 'ride_not_found'; end if;
  if ride_row.status <> 'searching' then
    if ride_row.driver_id = driver_uuid then return jsonb_build_object('ok', true, 'idempotent', true, 'ride_id', ride_row.id); end if;
    raise exception 'ride_already_assigned';
  end if;

  select * into driver_row from public.ride_drivers where id = driver_uuid for update;
  if driver_row.status <> 'available' or driver_row.verification_status <> 'verified' then raise exception 'driver_unavailable'; end if;
  select * into vehicle_row from public.driver_vehicles
  where driver_id = driver_uuid and category_id = ride_row.category_id and is_active and verification_status = 'verified'
  order by updated_at desc limit 1;
  if not found then raise exception 'verified_vehicle_unavailable'; end if;

  select * into wallet_row from public.professional_wallets where driver_id = driver_uuid for update;
  if not found or wallet_row.status <> 'active' then raise exception 'wallet_unavailable'; end if;
  commission_value := round(ride_row.estimated_amount * ride_row.commission_rate);
  if wallet_row.balance - wallet_row.reserved_balance < commission_value then raise exception 'wallet_insufficient'; end if;

  update public.professional_wallets set reserved_balance = reserved_balance + commission_value, updated_at = now() where id = wallet_row.id;
  insert into public.wallet_transactions(wallet_id, ride_id, transaction_type, amount, balance_after, reserved_after, idempotency_key, description)
  values(wallet_row.id, ride_uuid, 'reserve', commission_value, wallet_row.balance, wallet_row.reserved_balance + commission_value, operation_key, 'Commission Zeyds réservée à l’acceptation')
  on conflict (idempotency_key) do nothing;

  update public.rides set driver_id = driver_uuid, vehicle_id = vehicle_row.id, status = 'accepted', commission_amount = commission_value,
    driver_payout = estimated_amount, accepted_at = now(), updated_at = now() where id = ride_uuid;
  update public.ride_drivers set status = 'busy', updated_at = now() where id = driver_uuid;
  insert into public.ride_status_history(ride_id, previous_status, new_status, actor_user_id, actor_role)
  values(ride_uuid, 'searching', 'accepted', actor_uuid, 'driver');
  return jsonb_build_object('ok', true, 'ride_id', ride_uuid, 'commission_reserved', commission_value, 'vehicle_id', vehicle_row.id);
end;
$function$
;

CREATE OR REPLACE FUNCTION private.zeyds_audit_ride_admin_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  old_row jsonb := case when tg_op = 'INSERT' then null else to_jsonb(old) end;
  new_row jsonb := case when tg_op = 'DELETE' then null else to_jsonb(new) end;
  row_id text := coalesce(new_row->>'id', old_row->>'id');
begin
  insert into public.ride_admin_audit_log(actor_user_id, table_name, record_id, operation, old_data, new_data)
  values (auth.uid(), tg_table_name, row_id, tg_op, old_row, new_row);
  return case when tg_op = 'DELETE' then old else new end;
end;
$function$
;

CREATE OR REPLACE FUNCTION private.zeyds_create_driver_wallet()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  insert into public.professional_wallets(driver_id) values(new.id) on conflict (driver_id) do nothing;
  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION private.zeyds_ride_topic_uuid(topic_input text)
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
begin
  if topic_input !~ '^ride:[0-9a-fA-F-]{36}$' then return null; end if;
  return substring(topic_input from 6)::uuid;
exception when others then
  return null;
end;
$function$
;

CREATE OR REPLACE FUNCTION private.zeyds_transition_ride_atomic(ride_uuid uuid, target_status text, actor_uuid uuid, operation_key text, final_amount_input integer DEFAULT NULL::integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  ride_row public.rides%rowtype;
  wallet_row public.professional_wallets%rowtype;
  actor_driver uuid;
  allowed boolean := false;
  commission_value integer;
  final_price_value integer;
  stop_fee_value integer := 100;
  additional_stop_count integer := 0;
  adjusted_reserved integer;
  additional_commission integer;
begin
  if operation_key is null or length(trim(operation_key)) < 8 then raise exception 'idempotency_key_invalid'; end if;
  select * into ride_row from public.rides where id = ride_uuid for update;
  if not found then raise exception 'ride_not_found'; end if;
  actor_driver := private.zeyds_driver_for_user(actor_uuid);
  allowed := public.is_admin() or actor_uuid = ride_row.client_user_id or actor_driver = ride_row.driver_id;
  if not allowed then raise exception 'ride_forbidden'; end if;

  if target_status = 'driver_arriving' and ride_row.status = 'accepted' and actor_driver = ride_row.driver_id then null;
  elsif target_status = 'driver_arrived' and ride_row.status in ('accepted','driver_arriving') and actor_driver = ride_row.driver_id then null;
  elsif target_status = 'in_progress' and ride_row.status = 'driver_arrived' and actor_driver = ride_row.driver_id then null;
  elsif target_status = 'completed' and ride_row.status = 'in_progress' and actor_driver = ride_row.driver_id then null;
  elsif target_status = 'cancelled' and ride_row.status in ('searching','accepted','driver_arriving','driver_arrived') then null;
  elsif ride_row.status = target_status then return jsonb_build_object('ok', true, 'idempotent', true, 'ride_id', ride_uuid);
  else raise exception 'invalid_ride_transition';
  end if;

  if target_status = 'completed' then
    select * into wallet_row from public.professional_wallets where driver_id = ride_row.driver_id for update;
    if not found then raise exception 'wallet_unavailable'; end if;
    select coalesce(stop_fee, 100) into stop_fee_value from public.ride_pricing_settings
      where city_name = ride_row.city_name and is_active limit 1;
    select count(*)::integer into additional_stop_count from public.ride_stops where ride_id = ride_uuid;
    final_price_value := greatest(0,
      case when public.is_admin() and final_amount_input is not null then final_amount_input else ride_row.estimated_amount end
      + ride_row.waiting_amount + additional_stop_count * coalesce(stop_fee_value, 100));
    commission_value := round(final_price_value * ride_row.commission_rate);
    additional_commission := greatest(0, commission_value - ride_row.commission_amount);
    if wallet_row.balance - wallet_row.reserved_balance < additional_commission then raise exception 'wallet_insufficient_for_adjustment'; end if;
    adjusted_reserved := greatest(0, wallet_row.reserved_balance - ride_row.commission_amount + commission_value);

    if commission_value <> ride_row.commission_amount then
      update public.professional_wallets set reserved_balance = adjusted_reserved, updated_at = now() where id = wallet_row.id;
      insert into public.wallet_transactions(wallet_id, ride_id, transaction_type, amount, balance_after, reserved_after, idempotency_key, description, metadata)
      values(wallet_row.id, ride_uuid, 'adjustment', abs(commission_value - ride_row.commission_amount), wallet_row.balance,
        adjusted_reserved, operation_key || ':adjust', 'Réservation ajustée au prix final',
        jsonb_build_object('before', ride_row.commission_amount, 'after', commission_value))
      on conflict (idempotency_key) do nothing;
    end if;

    update public.professional_wallets set balance = balance - commission_value,
      reserved_balance = greatest(0, adjusted_reserved - commission_value), updated_at = now() where id = wallet_row.id;
    insert into public.wallet_transactions(wallet_id, ride_id, transaction_type, amount, balance_after, reserved_after, idempotency_key, description)
    values(wallet_row.id, ride_uuid, 'commission_debit', commission_value, wallet_row.balance - commission_value,
      greatest(0, adjusted_reserved - commission_value), operation_key, 'Commission Zeyds débitée séparément à la fin de course')
    on conflict (idempotency_key) do nothing;
    update public.rides set status = 'completed', final_amount = final_price_value, commission_amount = commission_value,
      driver_payout = final_price_value,
      payment_status = case when payment_method = 'cash' then 'cash_collected' else 'paid' end,
      completed_at = now(), updated_at = now() where id = ride_uuid;
    update public.ride_drivers set status = 'available', completed_rides = completed_rides + 1, updated_at = now() where id = ride_row.driver_id;
  elsif target_status = 'cancelled' then
    if ride_row.driver_id is not null and ride_row.commission_amount > 0 then
      select * into wallet_row from public.professional_wallets where driver_id = ride_row.driver_id for update;
      update public.professional_wallets set reserved_balance = greatest(0, reserved_balance - ride_row.commission_amount), updated_at = now() where id = wallet_row.id;
      insert into public.wallet_transactions(wallet_id, ride_id, transaction_type, amount, balance_after, reserved_after, idempotency_key, description)
      values(wallet_row.id, ride_uuid, 'release', ride_row.commission_amount, wallet_row.balance,
        greatest(0, wallet_row.reserved_balance - ride_row.commission_amount), operation_key, 'Commission libérée après annulation')
      on conflict (idempotency_key) do nothing;
      update public.ride_drivers set status = 'available', updated_at = now() where id = ride_row.driver_id;
    end if;
    update public.rides set status = 'cancelled', cancelled_by = case when public.is_admin() then 'admin' when actor_driver = ride_row.driver_id then 'driver' else 'client' end,
      cancelled_at = now(), updated_at = now() where id = ride_uuid;
  else
    update public.rides set status = target_status,
      driver_arrived_at = case when target_status = 'driver_arrived' then now() else driver_arrived_at end,
      started_at = case when target_status = 'in_progress' then now() else started_at end,
      updated_at = now() where id = ride_uuid;
  end if;

  insert into public.ride_status_history(ride_id, previous_status, new_status, actor_user_id, actor_role)
  values(ride_uuid, ride_row.status, target_status, actor_uuid,
    case when public.is_admin() then 'admin' when actor_driver = ride_row.driver_id then 'driver' else 'client' end);
  return jsonb_build_object('ok', true, 'ride_id', ride_uuid, 'status', target_status);
end;
$function$
;
